function appModal(message,{title='Подтверждение действия',danger=false,copyText=null}={}){
 return new Promise(resolve=>{
  const dialog=document.createElement('dialog');dialog.className='appConfirmDialog';
  const heading=document.createElement('h3');heading.textContent=copyText===null?title:'Скопировать текст';
  const paragraph=document.createElement('p');paragraph.textContent=message;
  const actions=document.createElement('div');actions.className='appConfirmActions';
  const cancel=document.createElement('button');cancel.type='button';cancel.className='ghost';cancel.textContent=copyText===null?'Отмена':'Закрыть';
  const accept=document.createElement('button');accept.type='button';accept.className=danger?'dangerAction':'primary';accept.textContent=copyText===null?'Подтвердить':'Скопировать';
  const body=document.createElement('div');body.className='appConfirmBody';body.append(heading,paragraph);
  let field;
  if(copyText!==null){field=document.createElement('textarea');field.readOnly=true;field.value=copyText;field.rows=7;body.append(field)}
  actions.append(cancel,accept);body.append(actions);dialog.append(body);document.body.append(dialog);
  let finished=false;function finish(result){if(finished)return;finished=true;dialog.close();dialog.remove();resolve(result)}
  cancel.onclick=()=>finish(false);
  accept.onclick=async()=>{if(field){try{await navigator.clipboard.writeText(field.value);finish(true)}catch(e){field.focus();field.select();accept.textContent='Выделено — скопируйте вручную'}}else finish(true)};
  dialog.addEventListener('cancel',e=>{e.preventDefault();finish(false)});
  dialog.showModal();
  if(field){field.focus();field.select()}else cancel.focus();
 });
}
