function required(a){return a.role==='Стажер'?4:5}function stateFor(a,x){if(x.status==='inactive')return{cls:'inactive',txt:'Неактив'};if(x.status==='norm'&&+x.norm>=required(a))return{cls:'norm',txt:'Выполнено'};if(x.status==='norm'&&+x.norm<required(a))return{cls:'low',txt:'Ниже нормы'};return{cls:'none',txt:'Нет данных'}}window.getNormImportStaff=()=>db.staff;
function normToHours(value){let s=String(value??'').trim().replace(',','.');if(/^\d{1,2}:\d{2}:\d{2}$/.test(s)){let p=s.split(':').map(Number);return p[1]<60&&p[2]<60?Number((p[0]+p[1]/60+p[2]/3600).toFixed(8)):NaN}return s!==''?Number(s):NaN}
